shared_html.shared_css:
/* ============ SHARED HEADER ============ */
.site-nav {
  font-family: 'Lato', system-ui, sans-serif;
  background: var(--surface);
  color: var(--text);
  border-bottom: 1px solid var(--accent);
}

.site-nav__band {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.4rem 1.6rem;
  gap: 1rem;
}

.site-nav__band--top {
  background: var(--primary);
  color: var(--bg);
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.site-nav__kicker { color: var(--accent); }
.site-nav__date  { color: var(--bg); opacity: 0.85; }

.site-nav__band--main {
  padding: 1rem 1.6rem;
  flex-wrap: wrap;
  border-top: 2px solid var(--ornament);
  border-bottom: 1px solid var(--accent);
}

.site-nav__wordmark {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  text-decoration: none;
  color: var(--text);
}

.site-nav__seal {
  display: inline-flex;
  width: 44px;
  height: 44px;
  border: 1px solid var(--ornament);
  padding: 1px;
  background: var(--bg);
}

.site-nav__title {
  display: flex;
  flex-direction: column;
  line-height: 1;
}

.site-nav__title-main {
  font-family: 'Yatra One', serif;
  font-size: 1.55rem;
  letter-spacing: 0.06em;
  color: var(--primary);
}

.site-nav__title-sub {
  margin-top: 0.3rem;
  font-size: 0.7rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--text-emphasis);
}

.site-nav__links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 1.4rem;
}

.site-nav__links a {
  font-size: 0.8rem;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--primary);
  padding: 0.4rem 0.1rem;
  border-bottom: 2px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}

.site-nav__links a:hover {
  color: var(--ornament);
  border-bottom-color: var(--accent);
}

.site-nav__rule {
  height: 6px;
  background:
    linear-gradient(var(--ornament), var(--ornament)) 0 0/100% 2px no-repeat,
    linear-gradient(var(--accent),   var(--accent))   0 4px/100% 1px no-repeat,
    var(--surface);
}

/* ============ SHARED FOOTER ============ */
.site-footer {
  position: relative;
  margin-top: 4rem;
  padding: 2.5rem 1.6rem 1.4rem;
  background: var(--primary);
  color: var(--bg);
  font-family: 'Lato', system-ui, sans-serif;
  font-size: 0.88rem;
}

.site-footer__rule {
  height: 8px;
  margin: -2.5rem -1.6rem 2rem;
  background:
    linear-gradient(var(--ornament), var(--ornament)) 0 0/100% 3px no-repeat,
    linear-gradient(var(--accent),   var(--accent))   0 5px/100% 1px no-repeat,
    var(--primary);
}

.site-footer__centerpiece {
  display: flex;
  justify-content: center;
  margin-bottom: 1.6rem;
}

.site-footer__cols {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 1.8rem;
  max-width: 1100px;
  margin: 0 auto;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--accent);
}

.site-footer__col h4 {
  font-family: 'Yatra One', serif;
  font-size: 0.95rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 0.7rem;
  padding-bottom: 0.35rem;
  border-bottom: 1px dotted var(--ornament);
}

.site-footer__col p {
  margin: 0;
  line-height: 1.6;
  color: var(--bg);
  opacity: 0.92;
}

.site-footer__col ul {
  list-style: none;
  margin: 0;
  padding: 0;
}

.site-footer__col li {
  padding: 0.18rem 0;
}

.site-footer__col li::before {
  content: "❋";
  color: var(--ornament);
  margin-right: 0.5rem;
  font-size: 0.7rem;
}

.site-footer__col a {
  color: var(--bg);
  text-decoration: none;
  border-bottom: 1px solid transparent;
}

.site-footer__col a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.site-footer__colophon {
  max-width: 1100px;
  margin: 1.4rem auto 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.6rem;
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--accent);
}

@media (max-width: 640px) {
  .site-nav__band { padding: 0.5rem 1rem; }
  .site-nav__band--main { flex-direction: column; align-items: flex-start; }
  .site-nav__links { gap: 0.2rem 1rem; }
  .site-footer { padding: 2rem 1rem 1.2rem; }
}
